/* Same draft and texture as the flat editor; only the viewing surface changes. */
(()=>{
 const M=window.Studio,V=window.Views;let api,gesture='rotate';
 const enabled=d=>d?.category==='enamel'&&Boolean(window.Vessels.data[d.canvas])&&d.editorSurface==='object';
 const switcher=d=>d.category==='enamel'&&Boolean(window.Vessels.data[d.canvas])?`<div class="editor-surface-tabs ui-segment" aria-label="编辑视图">${[['flat','① 做纹样'],['object','② 试器物']].map(([id,label])=>V.btn(label,'editor-surface','text',`data-id="${id}" aria-pressed="${enabled(d)===(id==='object')}"`)).join('')}</div>`:'';
 function stage(d){return `<div class="editor-object-stage">${V.btn('全屏','cup-open','text wb-fullscreen')}<small class="object-origin">${window.CupView.modelOrigin(d)}</small><div id="editor-cup-host" class="editor-cup-host"><div class="editor-static" hidden></div></div><div class="object-gesture-bar ui-segment">${V.btn('转动器物','editor-gesture','text',`data-id="rotate" aria-pressed="${gesture==='rotate'}"`)}${V.btn('摆放图案','editor-gesture','text',`data-id="place" aria-pressed="${gesture==='place'}" ${window.Vessels.hasPrint(d.vesselPlacement)?'':'disabled'}`)}${window.CupView.densityControl(d,gesture!=='place')}</div><p id="editor-object-status" role="status">正在建立器物预览…</p></div>`;}
 function status(state,message,previewDraft){const el=document.querySelector('#editor-object-status');if(!el)return;el.dataset.state=state;el.textContent=state==='ready'?(!window.Vessels.hasPrint((previewDraft||api.draft()).vesselPlacement)?'打开印花开关，将纹样放到此部位':gesture==='place'?(window.Vessels.isFill(window.Vessels.region(api.draft().canvas,api.draft().vesselPlacement.zone))?'拖动移动 · 双指调疏密与方向':'单指移动 · 双指缩放 / 转动纹样'):'轻点选部位 · 拖动转动 · 双指缩放'):message;const density=document.querySelector('.fill-density');if(density)density.hidden=state!=='fallback'&&gesture!=='place';const panel=document.querySelector('.editor-static');if(panel){panel.hidden=state!=='fallback';if(state==='fallback')panel.innerHTML=window.CupView.staticCup(previewDraft||api.draft());}document.querySelectorAll('[data-action=editor-gesture],[data-action=editor-camera]').forEach(el=>el.disabled=state==='fallback'||(el.dataset.action==='editor-gesture'&&el.dataset.id==='place'&&!window.Vessels.hasPrint((previewDraft||api.draft()).vesselPlacement)));if(['error','fallback'].includes(state))el.insertAdjacentHTML('beforeend',V.btn('重试','editor-retry','text'));}
 function mount(kept,force=false){const placeholder=document.querySelector('#editor-cup-host');if(!placeholder)return;if(kept){placeholder.replaceWith(kept);preview(api.draft());return;}window.Cup3D.mount(placeholder,api.draft(),camera=>{api.draft().cupCamera=camera;api.changed();},status,{force,interaction:()=>gesture,onPosition:id=>window.CupView.selectPosition(id,true),onPlacement:(patch,commit)=>{const d=api.draft();if(commit){M.edit(d,patch);api.changed();api.history();}const next={...d,...patch};preview(next);for(const key of ['x','y','scale','rotation']){const el=document.querySelector(`[data-field=${key}]`),out=document.querySelector(`[data-output=${key}]`);if(el)el.value=next[key];if(out)out.textContent=next[key];}}});}
 function preview(d){if(!document.querySelector('#editor-cup-host'))return false;window.CupView.syncCoverage(d);const density=document.querySelector('[data-fill-count]');if(density)density.value=window.Vessels.fillCount(window.Vessels.region(d.canvas,d.vesselPlacement.zone),d.vesselPlacement.scale);const chip=document.querySelector('.glaze-shortcut i');if(chip)chip.style.background=window.Vessels.glazeHex(d.cupMaterial?.color);if(window.Cup3D.diagnostics()?.mode==='static'){status('fallback','静态器物示意 · 不可旋转',d);}else window.Cup3D.update(d);return true;}
 function handle(action,el){if(action==='editor-surface'){window.Workbench?.closePanel();api.draft().editorSurface=el.dataset.id;api.changed();api.render();return true;}if(action==='editor-gesture'){if(el.dataset.id==='place'){if(!window.Vessels.hasPrint(api.draft().vesselPlacement))return true;window.CupView.focusPlacement();}gesture=el.dataset.id;const density=document.querySelector('.fill-density');if(density)density.hidden=gesture!=='place';document.querySelectorAll('[data-action=editor-gesture]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.id===gesture));status('ready','');return true;}if(action==='editor-camera'){window.Cup3D.control(el.dataset.id);return true;}if(action==='editor-retry'){api.draft().cupPreviewMode='three';api.changed();mount(null,true);return true;}return false;}
 window.EditorObject={enabled,switcher,stage,mount,preview,handle,place:()=>{gesture='place';},rotate:()=>{gesture='rotate';},init:ctx=>api=ctx};
})();
